<template>
  <div class="page-heading"><div><div class="eyebrow">RULE SETTINGS</div><h1>規則設定</h1><p>調整計算方式、適用條件與提醒天數。</p></div></div>
  <section class="panel"><div class="panel-head"><div><h2>{{ editing ? '編輯規則' : '新增自訂規則' }}</h2><p>{{ editing ? '預設規則不可修改代碼、對象或計算方式。' : '新增規則時只需填寫名稱，系統會提供代碼建議。' }}</p></div></div><div class="form-grid"><label v-if="!editing">規則代碼<input v-model="form.code" :placeholder="suggestedCode || '例如 annual_check'"/><small v-if="suggestedCode">建議代碼：{{ suggestedCode }}</small></label><label>規則名稱<input v-model="form.name" @input="suggestCode"/></label><label v-if="!editing">對象<select v-model="form.scope"><option v-for="[value,label] in scopes" :key="value" :value="value">{{ label }}</option></select></label><label v-if="!editing">計算方式<select v-model="form.method" @change="resetParams"><option v-for="[value,label] in methods" :key="value" :value="value">{{ label }}</option></select></label><label>提醒天數<input v-model.number="form.remindDays" type="number" min="0" max="730"/></label><label>客戶顯示<select v-model="form.customerVisible"><option :value="true">客戶可見</option><option :value="false">僅內部</option></select></label><label v-if="editing">啟用<select v-model="form.active"><option :value="true">啟用</option><option :value="false">停用</option></select></label>
    <label v-for="[key,label] in matchFields" :key="key">條件：{{ label }}<input v-model="conditions[key]" placeholder="不限；多個以、或,分隔"/></label>
    <div v-if="editing && form.paramsField === 'cardExpiresOn'" class="rule-source-note">資料來源：批文卡有效期（不可在此修改）</div>
    <template v-else-if="form.method==='yearly'"><label>月份<input v-model.number="params.month" type="number" min="1" max="12"/></label><label>日期<input v-model.number="params.day" type="number" min="1" max="31"/></label></template>
    <label v-else-if="form.method==='anniversary'">周年偏移天數<input v-model.number="params.offsetDays" type="number"/></label>
    <template v-else-if="form.method==='inspection'"><label>領標誌年份（可用、或,分隔）<input v-model="markYears"/></label><label>上線檢驗年份（可用、或,分隔）<input v-model="inspectYears"/></label><label>每年檢驗起始年<input v-model.number="params.yearlyFrom" type="number"/></label></template>
    <template v-else-if="form.method==='periodic'"><label>週期月份（可用、或,分隔）<input v-model="periodicMonths" placeholder="1、4、7、10"/></label><label>官方網址<input v-model="params.officialUrl" placeholder="https://"/></label></template></div><button class="button primary" @click="save">儲存規則</button><button v-if="editing" class="button" @click="reset">取消編輯</button></section>
  <section class="panel"><div class="panel-head"><div><h2>全部規則</h2><p>預設規則隱藏內部代碼，自訂規則只在編輯時顯示設定內容。</p></div></div><div v-for="rule in rules" :key="rule.id" class="record-row rule-row"><div><strong>{{ rule.name }}</strong><small>{{ label(scopes,rule.scope) }} · {{ label(methods,rule.method) }}</small></div><span>條件：{{ describe(rule.match) }}</span><span>參數：{{ rule.params.field === 'cardExpiresOn' ? '資料來源：批文卡有效期' : describe(rule.params) }}</span><span>提前 {{ rule.remind_days }} 天</span><span>{{ rule.customerVisible ? '客戶可見' : '僅內部' }}</span><span>{{ rule.active ? '啟用' : '停用' }}</span><button class="button" @click="edit(rule)">編輯</button></div></section>
</template>
<script setup>
import { ref, onMounted } from 'vue'
import { api } from '../api'
const emit = defineEmits(['error','saved'])
const scopes = [['plate','兩地牌'],['company','公司'],['vehicle','車輛']], methods = [['expiry','手動到期日'],['yearly','每年固定日期'],['anniversary','成立周年'],['inspection','驗車週期'],['periodic','定期核對']]
const matchFields = [['route','路線'],['jurisdiction','司法區'],['companyStatus','公司狀態'],['indicatorCategory','指標類別'],['port','口岸'],['origin','車輛來源地']]
const rules = ref([]), editing = ref(''), form = ref({}), conditions = ref({}), params = ref({}), markYears = ref(''), inspectYears = ref(''), periodicMonths = ref(''), suggestedCode = ref('')
const label = (choices,value) => choices.find(item => item[0] === value)?.[1] || value
const parameterLabels = {month:'月份',day:'日期',offsetDays:'周年偏移天數',markYears:'領標誌年份',inspectYears:'上線檢驗年份',yearlyFrom:'每年檢驗起始年',months:'週期月份',officialUrl:'官方網址'}
const describe = value => Object.keys(value).length ? Object.entries(value).map(([key,entry]) => `${matchFields.find(item=>item[0]===key)?.[1] || parameterLabels[key] || key}：${Array.isArray(entry) ? entry.join('、') : entry}`).join('；') : '不限'
const codeFromName = name => String(name || '').toLowerCase().replace(/[^a-z0-9\u4e00-\u9fff]+/g,'_').replace(/[\u4e00-\u9fff]/g,'rule').replace(/^_+|_+$/g,'').slice(0,40).replace(/^[^a-z]+/,'rule_') || 'custom_rule'
function suggestCode() { if (!editing.value) suggestedCode.value = codeFromName(form.value.name) }
function resetParams() { params.value = form.value.method === 'yearly' ? {month:1,day:1} : form.value.method === 'anniversary' ? {offsetDays:0} : form.value.method === 'inspection' ? {yearlyFrom:10} : form.value.method === 'periodic' ? {months:[1,4,7,10],officialUrl:'https://www.gsxt.gov.cn/'} : {} }
function reset() { editing.value = ''; suggestedCode.value = ''; form.value = {code:'',name:'',scope:'plate',method:'expiry',remindDays:30,active:true,customerVisible:true}; conditions.value = {}; resetParams(); markYears.value = '2,4,8'; inspectYears.value = '6'; periodicMonths.value = '1、4、7、10' }
async function load() { try { rules.value = await api('/rules') } catch (error) { emit('error',error) } }
function edit(rule) { editing.value = rule.id; form.value = {name:rule.name,scope:rule.scope,method:rule.method,remindDays:rule.remind_days,active:!!rule.active,customerVisible:rule.customerVisible ?? rule.customer_visible !== 0,paramsField:rule.params.field}; conditions.value = Object.fromEntries(Object.entries(rule.match).map(([key,value]) => [key,Array.isArray(value) ? value.join('、') : value])); params.value = {...rule.params}; markYears.value = rule.params.markYears?.join(',') || ''; inspectYears.value = rule.params.inspectYears?.join(',') || ''; periodicMonths.value = rule.params.months?.join('、') || '' }
async function save() { try { const match = Object.fromEntries(Object.entries(conditions.value).filter(([,value]) => String(value || '').trim()).map(([key,value]) => [key,value.split(/[、,]/).map(part=>part.trim()).filter(Boolean)])); const values = {...params.value}; if (form.value.method === 'inspection') { values.markYears = markYears.value.split(/[、,]/).filter(Boolean).map(Number); values.inspectYears = inspectYears.value.split(/[、,]/).filter(Boolean).map(Number) } if (form.value.method === 'periodic') values.months = periodicMonths.value.split(/[、,]/).filter(Boolean).map(Number); const body = {...form.value,code:form.value.code || suggestedCode.value,match,params:values}; delete body.paramsField; if (editing.value) { delete body.scope; delete body.method; delete body.code } await api(editing.value ? `/rules/${editing.value}` : '/rules',editing.value ? 'PATCH' : 'POST',body); reset(); await load(); emit('saved','規則已儲存') } catch (error) { emit('error',error) } }
onMounted(() => { reset(); load() })
</script>
